  // Logika spec var representing port state for outgoing data port
  @spec var gateEligibility: Station_Cargo_Transfer_Verification_Supervisor.ServiceEligibility.Type = $

  def put_gateEligibility(value : Station_Cargo_Transfer_Verification_Supervisor.ServiceEligibility.Type) : Unit = {
