    )
    Spec {
      gateEligibility = value
    }

    Art.putValue(gateEligibility_Id, Station_Cargo_Transfer_Verification_Supervisor.ServiceEligibility_Payload(value))
  }

  def logInfo(msg: String): Unit = {
