  @spec var serviceCondition: Station_Cargo_Transfer_Verification_Supervisor.DockServiceCondition.Type = $

  def get_serviceCondition() : Option[Station_Cargo_Transfer_Verification_Supervisor.DockServiceCondition.Type] = {
